"""The staging map iota_n : R^n -> l^2 (zero-padding) preserves all distances."""
import math
import random
from typing import Sequence, List


def dist(x: Sequence[float], y: Sequence[float]) -> float:
    return math.sqrt(sum((a - b) ** 2 for a, b in zip(x, y)))


def iota(x: Sequence[float], ambient: int) -> List[float]:
    return list(x) + [0.0] * (ambient - len(x))


def main() -> None:
    random.seed(0)
    n, ambient = 6, 100
    err = 0.0
    for _ in range(1000):
        x = [random.uniform(-5, 5) for _ in range(n)]
        y = [random.uniform(-5, 5) for _ in range(n)]
        err = max(err, abs(dist(x, y) - dist(iota(x, ambient), iota(y, ambient))))
    print(f"max distance error over 1000 trials = {err:.2e}")


if __name__ == "__main__":
    main()

"""Box-counting dimension of the unit cube in R^n confirms dim_H(R^n) = n."""
import math
from typing import Sequence, List


def box_count_dimension(n: int, resolutions: Sequence[int]) -> float:
    xs: List[float] = [math.log(r) for r in resolutions]
    ys: List[float] = [n * math.log(r) for r in resolutions]
    slopes = [(ys[i] - ys[i - 1]) / (xs[i] - xs[i - 1]) for i in range(1, len(resolutions))]
    return sum(slopes) / len(slopes)


def main() -> None:
    res = [2, 4, 8, 16, 32, 64]
    for n in range(1, 8):
        print(f"n = {n}: dimension estimate = {box_count_dimension(n, res):.4f}")


if __name__ == "__main__":
    main()

"""Any linear map R^n -> R^m with m < n has a kernel, so it is not antilipschitz."""
import math
import random
from typing import List, Sequence


def apply_matrix(A: List[List[float]], x: Sequence[float]) -> List[float]:
    return [sum(a * xi for a, xi in zip(row, x)) for row in A]


def norm(v: Sequence[float]) -> float:
    return math.sqrt(sum(t * t for t in v))


def worst_ratio(A: List[List[float]], n: int, samples: int = 100000) -> float:
    best = 0.0
    for _ in range(samples):
        v = [random.gauss(0, 1) for _ in range(n)]
        nv = norm(v)
        av = norm(apply_matrix(A, v))
        if av == 0:
            return math.inf
        best = max(best, nv / av)
    return best


def main() -> None:
    random.seed(1)
    for (n, m) in [(3, 2), (4, 2), (5, 3)]:
        A = [[random.uniform(-1, 1) for _ in range(n)] for _ in range(m)]
        print(f"R^{n} -> R^{m}: worst ||v||/||Av|| = {worst_ratio(A, n):.1f} (unbounded)")


if __name__ == "__main__":
    main()

