function IOTA(x[1..n], ambient):
    assert ambient >= n
    y <- array of length ambient filled with 0
    for i in 1..n:
        y[i] <- x[i]
    return y

# distance check
function IS_ISOMETRY(x, y, ambient):
    return dist(x, y) == dist(IOTA(x, ambient), IOTA(y, ambient))

