from typing import List, Sequence
import math


def iota(x: Sequence[float], ambient: int) -> List[float]:
    """Isometric embedding R^n -> R^ambient (finite view of l^2) by zero-padding."""
    n = len(x)
    if ambient < n:
        raise ValueError("ambient dimension must be at least n")
    return list(x) + [0.0] * (ambient - n)


def norm(v: Sequence[float]) -> float:
    return math.sqrt(sum(t * t for t in v))


def is_isometry(x: Sequence[float], y: Sequence[float], ambient: int) -> bool:
    du = norm([a - b for a, b in zip(x, y)])
    dv = norm([a - b for a, b in zip(iota(x, ambient), iota(y, ambient))])
    return math.isclose(du, dv, rel_tol=1e-12, abs_tol=1e-12)

