function BOX_DIMENSION(points, resolutions):
    for each r in resolutions:
        boxes <- empty set
        for each p in points:
            key <- tuple( floor(p[k] * r) for each coordinate k )
            boxes.add(key)
        N[r] <- size(boxes)
    fit line through { (log r, log N[r]) }
    return slope of the fitted line

function ANTILIPSCHITZ_CONSTANT(A[m][n]):
    G <- A^T A            # n x n Gram matrix
    lambda_min <- smallest eigenvalue of G
    if lambda_min <= 0:
        return INFINITY   # not antilipschitz (kernel is nontrivial)
    sigma_min <- sqrt(lambda_min)
    return 1 / sigma_min  # optimal antilipschitz constant K
